import sys; sys.path.insert(0,'/tmp/ss-build/tools/c10')
from lib10 import *
S='social-science'
def B(ch,cn,t,tn,*a,**k): build(S,ch,t,tn,*a,cname=cn,tname=tn,**k)
R="Both A and R are true and R explains A"
C,CN='eco-development','Economics 1: Development'
B(C,CN,'development','Development',
 "What does a good life mean?",
 "Ask a landless labourer, a rich farmer and a college student what development means and you will get three different answers. This chapter shows why, and how we compare countries.",
 [("Different people have different developmental goals. What is development for one may be unfair for another, and people often seek income, security, respect and freedom together.","different goals"),
  ("A common measure is average income, also called per capita income, which is the total income of a country divided by its total population.","per capita income"),
  ("Income alone is not enough. Public facilities like health, education and a public distribution system also matter, and the Human Development Report of UNDP compares countries using health, education and income.","income and human development"),
  ("Kerala has a low infant mortality rate and high literacy, though its per capita income is lower than that of states such as Haryana. So higher income does not always mean better human development.","Kerala vs Haryana"),
  ("The Human Development Index combines life expectancy, years of schooling and income per person to rank countries.","HDI"),
  ("Sustainability of development is also important. Resources like groundwater and fossil fuels are limited, so development must not harm future generations.","sustainability"),
  ("Averages can hide inequality. Two countries with the same average income may differ in how income is shared.","averages can mislead"),
  ("So development is a mix of income, public goods, equality and sustainability, not only money.","development is many-sided")],
 ("Country A has total income Rs 6,00,000 and 3,000 people. What is its per capita income?",[("Per capita income = total income / population.","Average per person."),("600000 / 3000 = Rs 200 per person.","Check 200 x 3000 = 600000.")]),
 ("Explain why income alone does not measure development.",["People want security, respect and health","Public facilities matter","Averages hide inequality"],["Thinking the richest country is the most developed"]),
 ["People have different developmental goals.","Per capita income is average income.","HDI uses health, education and income.","Development must be sustainable."],
 [mcq("e1-1",1,"Per capita income is","total income divided by population",[("total population divided by income","This reverses the formula."),("income of the richest","Not an average.")],"It is an average."),
  tf("e1-2",1,"A higher average income always means better human development.",False,"Kerala shows otherwise."),
  mcq("e1-3",2,"HDI measures","health, education and income",[("only income","Income is one of three."),("only schooling","It is one of three.")],"The UNDP uses them to compare countries."),
  mcq("e1-4",2,"Assertion (A): Averages can hide inequality. Reason (R): An average does not show how income is spread.",R,[("A true, R false","R explains A."),("Both false","Both correct.")],"Two countries may share an average but differ in spread."),
  short("e1-5",2,"Which organisation publishes the Human Development Report?",["undp","united nations development programme"],"The UNDP publishes it.",[("imf","IMF is a financial organisation.")]),
  mcq("e1-6",3,"Which state is highlighted for good health and literacy despite lower per capita income than Haryana?","Kerala",[("Bihar","Bihar ranks low."),("Punjab","Not the example.")],"Public services matter."),
  tf("e1-7",3,"Sustainable development protects future generations.",True,"It uses resources carefully."),
  num("e1-8",3,"If total income is Rs 90,000 and population is 30, per capita income (Rs) is",3000,"90000 / 30 = 3000.",[(300,"Check the zeros.")])])
C,CN='eco-sectors-of-the-indian-economy','Economics 2: Sectors of the Indian Economy'
B(C,CN,'sectors-of-the-indian-economy','Sectors of the Indian Economy',
 "Who gives you milk, makes your shoes and teaches you?",
 "A dairy farmer, a shoemaker and a teacher each work in a different sector of the economy. Today we classify economic work and see why jobs matter.",
 [("The primary sector uses natural resources, as in agriculture and dairy. The secondary sector turns raw material into goods, and the tertiary sector provides services such as transport, banking and teaching.","three sectors"),
  ("Gross Domestic Product (GDP) is the value of all final goods and services produced in a country in a year. Only final goods are counted to avoid double counting.","GDP"),
  ("Over time the tertiary sector has become the largest in GDP, but most workers are still employed in agriculture.","tertiary share"),
  ("Underemployment or disguised unemployment occurs when more people work than are needed, as when five family members work on land that needs two.","underemployment"),
  ("In the organised sector, jobs are regular and protected by laws. In the unorganised sector, jobs are irregular, wages are low and there is little protection.","organised vs unorganised"),
  ("The Mahatma Gandhi National Rural Employment Guarantee Act (MGNREGA), 2005 guarantees 100 days of employment in a year in rural areas.","MGNREGA 2005"),
  ("The public sector is owned and run by the government, while the private sector is owned by individuals or companies.","public and private"),
  ("The government supports sectors through irrigation, procurement and employment schemes so that the poor are protected.","government role")],
 ("A village produces 400 kg wheat and 100 kg flour from it. Why count only the flour in GDP if both are final?",[("Wheat used to make flour is an intermediate good.","It is used in producing flour."),("Counting both would double count the wheat value.","Count only the final goods.")]),
 ("Explain the difference between organised and unorganised sectors.",["Organised jobs are regular and protected","Unorganised jobs are irregular and unprotected","Examples"],["Thinking small farms are organised"]),
 ["There are three sectors: primary, secondary, tertiary.","GDP counts final goods and services.","MGNREGA guarantees 100 days of work.","Unorganised workers need protection."],
 [mcq("e2-1",1,"Dairy belongs to the","primary sector",[("secondary sector","Factory processing is secondary."),("tertiary sector","Services.")],"It depends on natural products."),
  tf("e2-2",1,"MGNREGA guarantees 100 days of work.",True,"It was enacted in 2005."),
  mcq("e2-3",2,"GDP counts","final goods and services",[("intermediate goods","They would double count."),("only exports","Not the definition.")],"Final value only."),
  mcq("e2-4",2,"Assertion (A): Unorganised workers need protection. Reason (R): Their jobs are irregular and low paid.",R,[("A true, R false","R is true."),("Both false","Both correct.")],"They lack legal safety."),
  short("e2-5",2,"What is a bank an example of: primary, secondary or tertiary?",["tertiary","tertiary sector"],"Banking is a service.",[("primary","Primary uses natural resources.")]),
  num("e2-6",2,"Guaranteed days of work under MGNREGA",100,"It guarantees 100 days.",[(50,"The guarantee is 100 days.")]),
  tf("e2-7",3,"Disguised unemployment means people are visibly jobless.",False,"People appear employed but extra workers add nothing."),
  mcq("e2-8",3,"A government-owned company belongs to the","public sector",[("private sector","Owned by individuals."),("unorganised sector","Not a ownership type.")],"The state owns and runs it.")])
C,CN='eco-money-and-credit','Economics 3: Money and Credit'
B(C,CN,'money-and-credit','Money and Credit',
 "Why not just swap goods?",
 "A shoemaker wants wheat, but the farmer wants cloth. Barter fails without a double coincidence of wants. Money solves this, and credit helps people start businesses.",
 [("In barter, goods are exchanged directly and it needs a double coincidence of wants. Money removes this trouble because it is accepted as a medium of exchange.","barter and money"),
  ("Modern forms of money are currency, paper notes and coins, and deposits with banks. In India the Reserve Bank of India issues currency notes.","RBI issues notes"),
  ("People keep money in bank accounts, which are demand deposits. Cheques allow payments without cash.","demand deposits"),
  ("Banks keep a part of deposits as cash and lend the rest. They earn interest on loans, which is more than they pay on deposits.","banks lend"),
  ("Credit or loan is an agreement where the lender supplies money and expects repayment. Terms of credit include interest rate, collateral, documentation and mode of repayment.","terms of credit"),
  ("Formal sources of credit are banks and cooperatives, supervised by the RBI. Informal sources are moneylenders and traders who often charge high interest.","formal and informal"),
  ("Self Help Groups pool small savings of 15 to 20 members, mostly women, and lend among themselves, which gives credit without collateral.","SHGs"),
  ("Debt trap occurs when a borrower cannot repay and falls deeper into debt. So cheap credit from formal sources is important.","debt trap")],
 ("A loan of Rs 10,000 at 10 per cent yearly simple interest. What interest after one year?",[("Interest = 10 per cent of 10,000.","10/100 x 10000."),("= Rs 1,000.","Repayment is 10,000 + 1,000 = Rs 11,000.")]),
 ("Why is formal credit better for poor households?",["Lower interest","Supervised by RBI","Avoids debt trap"],["Thinking moneylenders always charge the same"]),
 ["Money solves barter's double coincidence of wants.","RBI issues currency.","Formal credit is cheaper than informal credit.","SHGs help the poor with small loans."],
 [mcq("e3-1",1,"Who issues currency notes in India?","Reserve Bank of India",[("State Bank of India","A commercial bank."),("Finance Ministry","RBI issues notes.")],"RBI is the central bank."),
  tf("e3-2",1,"Barter needs a double coincidence of wants.",True,"Both sides must want what the other has."),
  mcq("e3-3",2,"Collateral is","an asset pledged for a loan",[("the interest rate","It is the cost."),("a bank account","Not a pledge.")],"It protects the lender."),
  mcq("e3-4",2,"Assertion (A): Formal credit should be extended to poor. Reason (R): Informal sources often charge very high interest.",R,[("A true, R false","R is true."),("Both false","Both correct.")],"High interest causes a debt trap."),
  short("e3-5",2,"Cheque is an example of which kind of deposit?",["demand deposit","demand deposits"],"Money can be withdrawn on demand.",[("fixed deposit","Not payable on demand.")]),
  mcq("e3-6",3,"A typical SHG has","15 to 20 members",[("2 members","Too few."),("200 members","Too many.")],"They pool savings."),
  tf("e3-7",3,"Moneylenders are part of the formal sector.",False,"Informal sector."),
  num("e3-8",3,"Interest (Rs) on Rs 5,000 at 10 per cent for one year",500,"10/100 x 5000 = 500.",[(50,"Multiply correctly.")])])
C,CN='eco-globalisation','Economics 4: Globalisation and the Indian Economy'
B(C,CN,'globalisation-and-the-indian-economy','Globalisation and the Indian Economy',
 "A shirt designed in one country, made in another",
 "The phone in your hand may have parts from many countries. Globalisation is the growing connection between economies through trade and investment.",
 [("Multinational corporations (MNCs) own or control production in more than one country. They set up offices and factories where costs are low and markets large.","MNCs"),
  ("MNCs spread production through foreign investment, joint ventures and by placing orders with small producers.","how MNCs spread"),
  ("Foreign trade connects markets in different countries. It gives producers and consumers more choices and can bring prices closer.","foreign trade"),
  ("Technology, such as telecommunication and the internet, has made globalisation faster.","technology"),
  ("In 1991 India adopted liberalisation: removing trade barriers and controls, and reforms in industries and foreign investment.","liberalisation 1991"),
  ("The World Trade Organisation (WTO) sets rules for international trade, but critics say rich countries have more power.","WTO"),
  ("Special Economic Zones (SEZs) were set up with world-class facilities and tax holidays to attract foreign companies.","SEZs"),
  ("The impact is unequal: consumers and some producers gained, but small producers and workers faced pressure. A fair globalisation would give opportunities to all.","impact")],
 ("India's exports are Rs 70 and imports Rs 50 (in crore). What is the trade surplus?",[("Surplus = exports minus imports.","Compare totals."),("70 - 50 = Rs 20 crore.","A positive result is a surplus.")]),
 ("Discuss how globalisation affects small producers.",["Competition from cheaper imports","Opportunities as suppliers to MNCs","Need for support and fair rules"],["Thinking globalisation benefits everyone equally"]),
 ["MNCs produce in more than one country.","India liberalised in 1991.","WTO and SEZs shape trade and investment.","Effects are unequal."],
 [mcq("e4-1",1,"An MNC is a company that","operates in more than one country",[("works only in one village","Local."),("is government-owned","Not defined by ownership.")],"It controls production across nations."),
  tf("e4-2",1,"India began liberalisation in 1991.",True,"Trade barriers were reduced."),
  mcq("e4-3",2,"WTO is concerned with","rules of international trade",[("school education","No."),("space research","No.")],"It sets rules for trade."),
  mcq("e4-4",2,"Assertion (A): Small producers may suffer under globalisation. Reason (R): They face competition from large firms and imports.",R,[("A true, R false","R is true."),("Both false","Both correct.")],"They need support."),
  short("e4-5",2,"What does SEZ stand for?",["special economic zone","special economic zones"],"They offer tax holidays.",[("state economic zone","Not the full form.")]),
  num("e4-6",2,"Year India began economic liberalisation",1991,"Reforms began in 1991.",[(1947,"Independence year.")]),
  mcq("e4-7",3,"Foreign trade can","give consumers more choices",[("end all competition","It increases competition."),("close markets","It opens them.")],"More goods are available."),
  tf("e4-8",3,"Technology plays no role in globalisation.",False,"Telecom and internet speed it up.")])
C,CN='eco-consumer-rights','Economics 5: Consumer Rights'
B(C,CN,'consumer-rights','Consumer Rights',
 "The packet that was not what it said",
 "You buy a packet of biscuits that is half-empty or a bulb that does not light. What can a consumer do? The law gives rights and a way to complain.",
 [("Markets can cheat consumers through low weights, adulteration, false advertising and high prices. So rules and awareness are needed.","exploitation"),
  ("The Consumer Protection Act 1986, known as COPRA, set up consumer courts at the district, state and national levels for settling disputes.","COPRA 1986"),
  ("A consumer can file a complaint at the District Forum for claims up to a limit, then the State Commission, and then the National Commission.","three-tier courts"),
  ("Consumer rights include the right to safety, to be informed, to choose, to be heard or represented, to seek redressal and to consumer education.","rights"),
  ("The Right to Information Act of 2005 lets citizens ask for information from government departments, and it helps people question delays.","RTI 2005"),
  ("Quality marks such as ISI, Agmark and Hallmark show standard goods. Consumers should check labels, dates and bills.","ISI, Agmark, Hallmark"),
  ("Consumer organisations and consumer forums help people by guiding and representing them in courts.","consumer forums"),
  ("Be an aware consumer: ask for a cash memo, check the price and quality, and complain when needed.","be aware")],
 ("A shop sells 'one kg' sugar that weighs 900 g. How many grams are short?",[("Subtract actual from claimed weight.","1 kg = 1000 g."),("1000 - 900 = 100 g short.","This is cheating by weight.")]),
 ("Explain how a consumer can seek redressal.",["Keep bills and proof","Complain to the consumer court","District, state and national levels"],["Thinking only big losses can be complained about"]),
 ["COPRA 1986 created consumer courts.","Consumers have six rights.","RTI 2005 helps citizens seek information.","ISI, Agmark and Hallmark show quality."],
 [mcq("e5-1",1,"COPRA stands for","Consumer Protection Act",[("Consumer Price Act","Not it."),("Central Price Authority","Not it.")],"It was enacted in 1986."),
  tf("e5-2",1,"Consumer courts exist at district, state and national levels.",True,"This is the three-tier system."),
  mcq("e5-3",2,"The Hallmark is for","gold jewellery",[("grain","Agmark covers grains."),("electrical goods","ISI.")],"It shows purity."),
  mcq("e5-4",2,"Assertion (A): Consumers should keep bills. Reason (R): Bills are proof of purchase.",R,[("A true, R false","R is true."),("Both false","Both correct.")],"Bills help in court."),
  short("e5-5",2,"Which mark certifies agricultural products?",["agmark"],"Agmark covers pulses, spices and so on.",[("isi","ISI is for industrial goods.")]),
  num("e5-6",2,"Year of the Consumer Protection Act",1986,"COPRA 1986.",[(2005,"RTI year.")]),
  mcq("e5-7",3,"The Right to Information Act was passed in","2005",[("1986","COPRA year."),("1991","Liberalisation.")],"RTI came in 2005."),
  tf("e5-8",3,"Consumers have the right to be informed.",True,"It is one of the six rights.")])
print('econ ok')
